// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public {
        c = new DnGmxBatchingManager();
    }

    function testFuzz_property(address k, address owner_) public {
        // Admissible domain: k must be non-zero so the reference's stored keeper differs from the mutant's address(0).
        // This is a WIDE domain restriction, not a dodge: the bug's forced initial keeper is address(0),
        // so only k != 0 can separate the two on the keeper getter.
        vm.assume(k != address(0));

        // The test contract deployed c in setUp, so it is the owner at initialization.
        // We need an initialized instance. initialize requires a plausible set of addresses; the
        // reference does not validate them beyond storing, EXCEPT glpManager.vault() is called
        // through, so we route that through a tiny helper that returns a benign address.
        Helper helper = new Helper();

        c.initialize(
            IERC20(address(helper)),
            IERC20(address(helper)),
            IRewardRouterV2(address(helper)),
            IGlpManager(address(helper)),
            address(helper),
            k
        );

        // After initialize with _keeper = k, the reference stores k as keeper.
        // The mutant's initialize ignores _keeper and stores address(0).
        // So the general rule: the keeper recorded at construction is exactly the keeper argument.
        assertTrue(c.keeper() == k);
    }
}

// Minimal helper so that the internal init's glpManager.vault() call succeeds.
// Only used as a non-code-requiring address for the other slots; vault() returns this address.
contract Helper {
    function vault() external view returns (address) {
        return address(this);
    }
}
